begin;
create temp table _had_note on commit drop as select id from public.areas where parking_note is not null;
update public.areas set parking_note='Park in the designated, labeled climber parking on the far side of the golf course clubhouse lot on Brow Lake Rd, then sign in at the clubhouse and pay the day-use fee before climbing.' where id='tn_stone_fort_bouldering_climbs' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the designated, labeled climber parking on the far side of the golf course clubhouse lot on Brow Lake Rd, then sign in at the clubhouse and pay the day-use fee before climbing.' where path <@ (select path from public.areas where id='tn_stone_fort_bouldering_climbs') and id <> 'tn_stone_fort_bouldering_climbs' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park in the lot on Mullens Cove Rd in Prentice Cooper State Forest; the approach trail starts across the road from it. Parking along the road is not allowed, and break-ins have happened, so leave nothing in the car.' where id='tn_t_wall_east' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the lot on Mullens Cove Rd in Prentice Cooper State Forest; the approach trail starts across the road from it. Parking along the road is not allowed, and break-ins have happened, so leave nothing in the car.' where path <@ (select path from public.areas where id='tn_t_wall_east') and id <> 'tn_t_wall_east' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park at the informal pull-offs along the Potash Road (UT 279), about 2 miles in from US-191; the routes are right beside the road. Park well out of the traffic lane, as potash trucks and 4x4s use it.' where id='ut_wall_street' and id not in (select id from _had_note);
update public.areas set parking_note='Park at the informal pull-offs along the Potash Road (UT 279), about 2 miles in from US-191; the routes are right beside the road. Park well out of the traffic lane, as potash trucks and 4x4s use it.' where path <@ (select path from public.areas where id='ut_wall_street') and id <> 'ut_wall_street' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park in the dirt lot at the end of Front Street in Grand Ledge (turn left onto Front St just after crossing the bridge on Bridge St, through the subdivision). Trails lead a few minutes downhill to the boulders; do not park at Fitzgerald Park across the river.' where id='mi_bouldering' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the dirt lot at the end of Front Street in Grand Ledge (turn left onto Front St just after crossing the bridge on Bridge St, through the subdivision). Trails lead a few minutes downhill to the boulders; do not park at Fitzgerald Park across the river.' where path <@ (select path from public.areas where id='mi_bouldering') and id <> 'mi_bouldering' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='The approach trail starts at the south end of the Poke-O-Moonshine campground off NY 9 (kiosk at the trailhead). Roadside parking is limited and the campground is described as closed in places, so check posted notices.' where id='ny_poke_o_moonshine_main_face' and id not in (select id from _had_note);
update public.areas set parking_note='The approach trail starts at the south end of the Poke-O-Moonshine campground off NY 9 (kiosk at the trailhead). Roadside parking is limited and the campground is described as closed in places, so check posted notices.' where path <@ (select path from public.areas where id='ny_poke_o_moonshine_main_face') and id <> 'ny_poke_o_moonshine_main_face' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Park in the lot on the east side of Centennial Dr, about 1/2 mile north of CR-38E (1 mile south of CR-42C). It is shared with the Piano Keys boulders; hike west up the hogback about 5 minutes to the ridge.' where id='co_duncan_s_ridge' and id not in (select id from _had_note);
update public.areas set parking_note='Park in the lot on the east side of Centennial Dr, about 1/2 mile north of CR-38E (1 mile south of CR-42C). It is shared with the Piano Keys boulders; hike west up the hogback about 5 minutes to the ridge.' where path <@ (select path from public.areas where id='co_duncan_s_ridge') and id <> 'co_duncan_s_ridge' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Turn onto Airport Road and follow it 2.5 miles to the locked gate; park there without blocking the gate, then walk the dirt road past the second gate and take the faint trail left toward the lake.' where id='wv_long_point' and id not in (select id from _had_note);
update public.areas set parking_note='Turn onto Airport Road and follow it 2.5 miles to the locked gate; park there without blocking the gate, then walk the dirt road past the second gate and take the faint trail left toward the lake.' where path <@ (select path from public.areas where id='wv_long_point') and id <> 'wv_long_point' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='A larger lot sits at the base of Palisade Head on Hwy 61 with a trail to the top, and a small lot is near the summit. Parking is very tight in blueberry season, so arrive early; climbers need a Tettegouche State Park permit.' where id='mn_palisade_head' and id not in (select id from _had_note);
update public.areas set parking_note='A larger lot sits at the base of Palisade Head on Hwy 61 with a trail to the top, and a small lot is near the summit. Parking is very tight in blueberry season, so arrive early; climbers need a Tettegouche State Park permit.' where path <@ (select path from public.areas where id='mn_palisade_head') and id <> 'mn_palisade_head' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Options include street parking on Sheldon (downhill side) and Moore Hill, or the Timberlin Park lot with a trail north to the cliff. Do not block driveways or mailboxes, and obey no-parking signs.' where id='ct_main_cliff' and id not in (select id from _had_note);
update public.areas set parking_note='Options include street parking on Sheldon (downhill side) and Moore Hill, or the Timberlin Park lot with a trail north to the cliff. Do not block driveways or mailboxes, and obey no-parking signs.' where path <@ (select path from public.areas where id='ct_main_cliff') and id <> 'ct_main_cliff' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
update public.areas set parking_note='Access is through the double gate and gravel road to the newly built parking area; lock the gate behind you. The land is private with a climbing easement, so check current gate and parking conditions before going.' where id='ca_jailhouse_rock' and id not in (select id from _had_note);
update public.areas set parking_note='Access is through the double gate and gravel road to the newly built parking area; lock the gate behind you. The land is private with a climbing easement, so check current gate and parking conditions before going.' where path <@ (select path from public.areas where id='ca_jailhouse_rock') and id <> 'ca_jailhouse_rock' and id not in (select id from _had_note) and parking_note is null and parking_lat is null;
commit;
